import{_ as o,o as d,c as t,a5 as c}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"基于代理 Dao 实现 CRUD 操作","description":"","frontmatter":{"title":"基于代理 Dao 实现 CRUD 操作","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/基于代理 Dao 实现 CRUD 操作.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/基于代理 Dao 实现 CRUD 操作.md"}'),s={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/基于代理 Dao 实现 CRUD 操作.md"};function r(a,e,n,i,u,l){return d(),t("div",null,[...e[0]||(e[0]=[c("<div><p><code>mybatis</code> <strong>环境搭建步骤</strong> 第一步：创建 <code>maven</code> 工程 第二步：导入坐标 第三步：编写必要代码（实体类和持久层接口） 第四步：编写 <code>SqlMapConfig.xml</code> 第五步：编写映射配置文件 第六步：编写测试类</p><p><strong>使用要求：</strong><code>1</code>、持久层接口和持久层接口的映射配置必须在相同的包下 <code>2</code>、持久层映射配置中 <code>mapper</code> 标签的 <code>namespace</code> 属性取值必须是持久层接口的全限定类名 <code>3</code>、<code>SQL</code> 语句的配置标签<code>\\&lt;select\\&gt;,\\&lt;insert\\&gt;,\\&lt;delete\\&gt;,\\&lt;update\\&gt;</code>的 <code>id</code> 属性必须和持久层接口的 方法名相同。</p><p><strong>根据</strong> <code>ID</code> <strong>查询</strong><code>1</code> <strong>在持久层接口中添加</strong> <code>findById</code> <strong>方法</strong></p><p>/** * 根据 <code>id</code> 查询</p><ul><li>@param userId</li><li>@return */ User findById(Integer userId);</li></ul><p><code>2</code> <strong>在用户的映射配置文件中配置</strong><code>\\&lt;!--</code> 根据 <code>id</code> 查询</p><p>--&gt; &lt;select id=&quot;findById&quot; resultType=&quot;com.itheima.domain.User&quot; parameterType=&quot;int&quot;&gt; select * from user where id = #{uid} &lt;/select&gt; <strong>细节：</strong><code>resultType</code> **属性：**用于指定结果集的类型。 <code>parameterType</code> <strong>属性</strong>：用于指定传入参数的类型。 <code>sql</code> <strong>语句中使用</strong><code>#{}</code>**字符：**它代表占位符，相当于原来 <code>jdbc</code> 部分所学的<code>?</code>，都是用于执行语句时替换实际的数据。具体的数据是由<code>#{}</code>里面的内容决定的。 <code>#{}</code>**中内容的写法：**由于数据类型是基本类型，所以此处可以随意写。</p><p><code>3</code> <strong>在测试类添加测试</strong></p><p>public class MybastisCRUDTest { private InputStream in ; private SqlSessionFactory factory; private SqlSession session; private IUserDao userDao; @Test public void testFindOne() { //6. 执行操作</p><p>User user = userDao.findById(41); System.out.println(user); } @Before// 在测试方法执行之前执行</p><p>public void init()throws Exception { //1. 读取配置文件</p><p>in = Resources.getResourceAsStream(&quot;SqlMapConfig.xml&quot;); //2. 创建构建者对象</p><p>SqlSessionFactoryBuilder builder = new SqlSessionFactoryBuilder(); //3. 创建 <code>SqlSession</code> 工厂对象</p><p>factory = builder.build(in); //4. 创建 <code>SqlSession</code> 对象</p><p>session = factory.openSession(); //5. 创建 <code>Dao</code> 的代理对象</p><p>userDao = session.getMapper(IUserDao.class); } @After// 在测试方法执行完成之后执行</p><p>public void destroy() throws Exception{ session.commit(); //7. 释放资源</p><p>session.close(); in.close(); } }</p><p><code>2.2</code> <strong>保存操作</strong><code>2.2.1</code> <strong>在持久层接口中添加新增方法</strong></p><p>/** * 保存用户</p><ul><li>@param user</li><li>@return 影响数据库记录的行数</li></ul><p>*/ int saveUser(User user); 2.2.2 <strong>在用户的映射配置文件中配置</strong><code>\\&lt;!--</code> 保存用户</p><p>--&gt; &lt;insert id=&quot;saveUser&quot; parameterType=&quot;com.itheima.domain.User&quot;&gt; insert into user(username,birthday,sex,address) values(#{username},#{birthday},#{sex},#{address}) &lt;/insert&gt; <strong>细节：</strong><code>parameterType</code> 属性： 代表参数的类型，因为我们要传入的是一个类的对象，所以类型就写类的全名称。 <code>sql</code> 语句中使用<code>#{}</code>字符： 它代表占位符，相当于原来 <code>jdbc</code> 部分所学的<code>?</code>，都是用于执行语句时替换实际的数据。 具体的数据是由<code>#{}</code>里面的内容决定的。 <code>#{}</code>中内容的写法： 由于我们保存方法的参数是 一个 <code>User</code> 对象，此处要写 <code>User</code> 对象中的属性名称。 它用的是 <code>ognl</code> 表达式。 <code>ognl</code> 表达式： 它是 <code>apache</code> 提供的一种表达式语言，全称是： <code>Object Graphic Navigation Language</code> 对象图导航语言 它是按照一定的语法格式来获取数据的。 语法格式就是使用 <code>#{</code>对象<code>.</code>对象<code>}</code>的方式传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 #{user.username} 它会先去找 <code>user</code> 对象，然后在 <code>user</code> 对象中找到 <code>username</code> 属性，并调用 <code>getUsername()</code>方法把值取出来。但是我们在 <code>parameterType</code> 属性上指定了实体类名称，所以可以省略 <code>user.</code> 而直接写 <code>username</code>。 <code>2.2.3</code> <strong>添加测试类中的测试方法</strong></p><p>@Test public void testSave(){ User user = new User(); user.setUsername(&quot;modify User property&quot;); user.setAddress(&quot; <code>北京市顺义区</code> &quot;); user.setSex(&quot; <code>男</code> &quot;); user.setBirthday(new Date()); System.out.println(&quot; <code>保存操作之前：</code> &quot;+user); //5. <code>执行保存方法</code> userDao.saveUser(user); System.out.println(&quot; <code>保存操作之后：</code> &quot;+user); } 打开 <code>Mysql</code> 数据库发现并没有添加任何记录，原因是什么？ 这一点和 <code>jdbc</code> 是一样的，我们在实现增删改时一定要去控制事务的提交，那么在 <code>mybatis</code> 中如何控制事务 提交呢？ 可以使用<code>:session.commit();</code>来实现事务提交。加入事务提交后的代码如下：</p><p>@After// <code>在测试方法执行完成之后执行</code> public void destroy() throws Exception{ session.commit(); //7. <code>释放资源</code> session.close(); in.close(); } 2.2.4 <strong>问题扩展：新增用户</strong> <code>id</code> <strong>的返回值</strong> 新增用户后，同时还要返回当前新增用户的 <code>id</code> 值，因为 <code>id</code> 是由数据库的自动增长来实现的，所以就相 当于我们要在新增后将自动增长 <code>auto_increment</code> 的值返回。</p><p>&lt;insert id=&quot;saveUser&quot; parameterType=&quot;USER&quot;&gt; &lt;!-- <code>**配置保存时获取插入的**</code> id --&gt; &lt;selectKey keyColumn=&quot;id&quot; keyProperty=&quot;id&quot; resultType=&quot;int&quot;&gt; select last_insert_id(); &lt;/selectKey&gt; insert into user(username,birthday,sex,address) values(#{username},#{birthday},#{sex},#{address}) &lt;/insert&gt;</p><ul><li>传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训</li><li>`</li><li><code>2.3</code> <strong>用户更新</strong></li><li><code>2.3.1</code> <strong>在持久层接口中添加更新方法</strong></li></ul><p>/** * <code>更新用户</code></p><ul><li>@param user</li><li>@return <code>影响数据库记录的行数</code> */ int updateUser(User user); 2.3.2</li></ul><ul><li><strong>在用户的映射配置文件中配置</strong></li><li><code>\\&lt;!--</code> 更新用户</li></ul><p>--&gt; &lt;update id=&quot;updateUser&quot; parameterType=&quot;com.itheima.domain.User&quot;&gt; update user set username=#{username},birthday=#{birthday},sex=#{sex}, address=#{address} where id=#{id} &lt;/update&gt; 2.3.3 <code>**加入更新的测试方法**</code> @Test public void testUpdateUser()throws Exception{ //1. <code>根据 </code>id<code> 查询</code> User user = userDao.findById(52); //2. <code>更新操作</code> user.setAddress(&quot; <code>北京市顺义区</code> &quot;); int res = userDao.updateUser(user); System.out.println(res); }</p><ul><li><code>2.4</code> <strong>用户删除</strong></li><li><code>2.4.1</code> <strong>在持久层接口中添加删除方法</strong></li></ul><p>/** * <code>根据 </code>id<code> 删除用户</code></p><ul><li>@param userId</li><li>@return */ 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 int deleteUser(Integer userId); 2.4.2 <strong>在用户的映射配置文件中配置</strong><code>\\&lt;!--</code> 删除用户</li></ul><p>--&gt; &lt;delete id=&quot;deleteUser&quot; parameterType=&quot;java.lang.Integer&quot;&gt; delete from user where id = #{uid} &lt;/delete&gt; 2.4.3 <strong>加入删除的测试方法</strong></p><p>@Test public void testDeleteUser() throws Exception { //6. 执行操作</p><p>int res = userDao.deleteUser(52); System.out.println(res); }</p><p><code>2.5</code> <strong>用户模糊查询</strong><code>2.5.1</code> <strong>在持久层接口中添加模糊查询方法</strong></p><p>/** * 根据名称模糊查询</p><ul><li>@param username</li><li>@return */ List&lt;User&gt; findByName(String username); 2.5.2 <strong>在用户的映射配置文件中配置</strong><code>\\&lt;!--</code> 根据名称模糊查询</li></ul><p>--&gt; &lt;select id=&quot;findByName&quot; resultType=&quot;com.itheima.domain.User&quot; parameterType=&quot;String&quot;&gt; select * from user where username like #{username} &lt;/select&gt; 2.5.3 <strong>加入模糊查询的测试方法</strong></p><p>@Test public void testFindByName(){ 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 //5. <code>执行查询一个方法</code> List&lt;User&gt; users = userDao.findByName(&quot;% <code>王</code> %&quot;); for(User user : users){ System.out.println(user); } } 在控制台输出的执行 <code>SQL</code> 语句如下： 我们在配置文件中没有加入<code>%</code>来作为模糊查询的条件，所以在传入字符串实参时，就需要给定模糊查询的标 识<code>%</code>。配置文件中的<code>#{username}</code>也只是一个占位符，所以 <code>SQL</code> 语句显示为“？”。 <code>2.5.4</code> <strong>模糊查询的另一种配置方式</strong> 第一步：修改 <code>SQL</code> 语句的配置，配置如下： <code>\\&lt;!--</code> 根据名称模糊查询</p><p>--&gt; &lt;select id=&quot;findByName&quot; parameterType=&quot;string&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select * from user where username like &#39;%${value}%&#39; &lt;/select&gt; 我们在上面将原来的<code>#{}</code>占位符，改成了<code>${value}</code>。注意如果用模糊查询的这种写法，那么<code>${value}</code>的写 法就是固定的，不能写成其它名字。 第二步：测试，如下：</p><p>/** * <code>测试模糊查询操作</code> */ @Test public void testFindByName(){ //5. <code>执行查询一个方法</code> List&lt;User&gt; users = userDao.findByName(&quot; <code>王</code> &quot;); for(User user : users){ System.out.println(user); } } 在控制台输出的执行 <code>SQL</code> 语句如下： 可以发现，我们在程序代码中就不需要加入模糊查询的匹配符<code>%</code>了，这两种方式的实现效果是一样的，但执行 的语句是不一样的。传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 2.5.5 #{} <strong>与</strong><code>${}</code><strong>的区别</strong><code>#{}</code><strong>表示一个占位符号</strong> 通过<code>#{}</code>可以实现 <code>preparedStatement</code> 向占位符中设置值，自动进行 <code>java</code> 类型和 <code>jdbc</code> 类型转换， <code>#{}</code>可以有效防止 <code>sql</code> 注入。 <code>#{}</code>可以接收简单类型值或 <code>pojo</code> 属性值。 如果 <code>parameterType</code> 传输单个简单类 型值，<code>#{}</code>括号中可以是 <code>value</code> 或其它名称。 <code>${}</code><strong>表示拼接</strong> <code>sql</code> <strong>串</strong> 通过<code>${}</code>可以将 <code>parameterType</code> 传入的内容拼接在 <code>sql</code> 中且不进行 <code>jdbc</code> 类型转换， <code>${}</code>可以接收简 单类型值或 <code>pojo</code> 属性值，如果 <code>parameterType</code> 传输单个简单类型值，<code>${}</code>括号中只能是 <code>value</code>。 <code>2.5.6</code> <strong>模糊查询的</strong><code>${value}</code><strong>源码分析</strong> 我们一起来看 <code>TextSqlNode</code> 类的源码： 这就说明了源码中指定了读取的 <code>key</code> 的名字就是”<code>value</code>”，所以我们在绑定参数时就只能叫 <code>value</code> 的名字 了。</p><p><code>2.6</code> <strong>查询使用聚合函数</strong><code>2.6.1</code> <strong>在持久层接口中添加模糊查询方法</strong></p><p>/** * 查询总记录条数</p><ul><li>@return */ int findTotal(); 2.6.2 <strong>在用户的映射配置文件中配置</strong><code>\\&lt;!--</code> 查询总记录条数</li></ul><p>--&gt; &lt;select id=&quot;findTotal&quot; resultType=&quot;int&quot;&gt; select count(*) from user; 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 &lt;/select&gt; 2.6.3 <code>**加入聚合查询的测试方法**</code> @Test public void testFindTotal() throws Exception { //6. <code>执行操作</code> int res = userDao.findTotal(); System.out.println(res); }</p><p><code>2.7 Mybatis</code> <strong>与</strong> <code>JDBC</code> <strong>编程的比较</strong><code>1.</code>数据库链接创建、释放频繁造成系统资源浪费从而影响系统性能，如果使用数据库链接池可解决此问题。 解决： 在 <code>SqlMapConfig.xml</code> 中配置数据链接池，使用连接池管理数据库链接。 <code>2.Sql</code> 语句写在代码中造成代码不易维护，实际应用 <code>sql</code> 变化的可能较大，<code>sql</code> 变动需要改变 <code>java</code> 代码。 解决： 将 <code>Sql</code> 语句配置在 <code>XXXXmapper.xml</code> 文件中与 <code>java</code> 代码分离。 <code>3.</code>向 <code>sql</code> 语句传参数麻烦，因为 <code>sql</code> 语句的 <code>where</code> 条件不一定，可能多也可能少，占位符需要和参数对应。 解决： <code>Mybatis</code> 自动将 <code>java</code> 对象映射至 <code>sql</code> 语句，通过 <code>statement</code> 中的 <code>parameterType</code> 定义输入参数的 类型。 <code>4.</code>对结果集解析麻烦，<code>sql</code> 变化导致解析代码变化，且解析前需要遍历，如果能将数据库记录封装成 <code>pojo</code> 对 象解析比较方便。 解决： <code>Mybatis</code> 自动将 <code>sql</code> 执行结果映射至 <code>java</code> 对象，通过 <code>statement</code> 中的 <code>resultType</code> 定义输出结果的 类型。</p></div>",1)])])}const m=o(s,[["render",r]]);export{g as __pageData,m as default};
